// --- Prefix Sum Array ---

// Function to compute prefix sums of an array
std::vector<long long> prefixSum(const std::vector<int>& arr) {
    int n = arr.size();
    std::vector<long long> ps(n + 1, 0); // Initialize prefix sum array with extra space for S[0]
    for (int i = 1; i <= n; ++i) {
        ps[i] = ps[i - 1] + arr[i - 1]; // Compute prefix sum up to index i-1
    }
    return ps;
}

// --- Difference Array ---

// Function to apply range updates using difference array
std::vector<int> applyUpdates(const std::vector<int>& diff, int n) {
    std::vector<int> result(n); // Initialize result array
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            result[i] = diff[i]; // First element is the same as in difference array
        } else {
            result[i] = result[i - 1] + diff[i]; // Compute value from previous and current difference
        }
    }
    return result;
}

// --- Main Function for Usage Example ---

int main() {
    std::vector<int> arr = {3, 1, 4, 1, 5};
    int n = arr.size();

    // Compute prefix sums
    auto ps = prefixSum(arr);
    std::cout << "Prefix Sum Array: ";
    for (int i = 0; i <= n; ++i) {
        std::cout << ps[i] << " ";
    }
    std::cout << std::endl;

    // Define difference array for updates
    std::vector<int> diff(n + 1, 0);
    diff[2] = 2; // Increase elements from index 2 to n-1 by 2
    diff[4] = -3; // Decrease elements from index 4 to n-1 by 3

    // Apply updates and compute final array
    auto updatedArr = applyUpdates(diff, n);
    std::cout << "Updated Array: ";
    for (int i = 0; i < n; ++i) {
        std::cout << updatedArr[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

