// --- build adjacency list ---
#include <vector>
#include <list>

using namespace std;

// Function to build an adjacency list from a list of edges
vector<list<int>> buildAdjacencyList(const vector<pair<int, int>>& edges) {
    // Time: O(E), Space: O(V + E)
    int V = 0;
    for (const auto& edge : edges) {
        V = max(V, max(edge.first, edge.second));
    }
    vector<list<int>> adjList(V + 1);
    for (const auto& edge : edges) {
        adjList[edge.first].push_back(edge.second);
        adjList[edge.second].push_back(edge.first);
    }
    return adjList;
}

