// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- find connected components ---
void dfs(int node, std::vector<std::vector<int>>& adj, std::vector<bool>& visited, std::vector<int>& component) {
    visited[node] = true;
    component.push_back(node);
    for (int neighbor : adj[node]) {
        if (!visited[neighbor]) {
            dfs(neighbor, adj, visited, component);
        }
    }
}

std::vector<std::vector<int>> find_connected_components(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj = build_adjacency_list(edges, n);
    std::vector<bool> visited(n, false);
    std::vector<std::vector<int>> components;
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            std::vector<int> component;
            dfs(i, adj, visited, component);
            components.push_back(component);
        }
    }
    return components;
}

