// --- Bubble Sort Implementation ---

#include <vector>
#include <algorithm>

// Function to perform Bubble Sort on a vector of integers
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    // Outer loop for each element in the array
    for (int i = 0; i < n - 1; ++i) {
        swapped = false;
        // Inner loop for comparing adjacent elements
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
                swapped = true;
            }
        }
        // If no swaps were made, the array is already sorted
        if (!swapped) break;
    }
}

// --- Complexity Analysis ---
// Time: O(n^2) in the worst and average case, O(n) in the best case when the array is already sorted.
// Space: O(1) as it sorts the array in place without using any extra space.

