// --- Kadane's Algorithm ---

// Time: O(n) — Space: O(1)

#include <vector>
#include <algorithm>

long long kadane(const std::vector<int>& nums) {
    // Initialize variables to store the maximum sum and the current sum
    long long max_sum = nums[0];
    long long current_sum = nums[0];

    // Iterate through the array starting from the second element
    for (size_t i = 1; i < nums.size(); ++i) {
        // Update the current sum to be the maximum of the current element or the current sum plus the current element
        current_sum = std::max(nums[i], current_sum + nums[i]);

        // Update the maximum sum if the current sum is greater
        max_sum = std::max(max_sum, current_sum);
    }

    return max_sum;
}

