// --- Monotonic Stack Implementation ---

#include <vector>
#include <stack>
#include <iostream>

// Function to find the next greater element for each position in an array
std::vector<int> nextGreaterElement(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> result(n, -1); // Initialize result with -1
    std::stack<int> stack; // Stack to store indices of elements

    for (int i = 0; i < n; ++i) {
        // While stack is not empty and current element is greater than the element at the index stored at the top of the stack
        while (!stack.empty() && nums[i] > nums[stack.top()]) {
            result[stack.top()] = nums[i]; // Update result for the element at the top of the stack
            stack.pop(); // Pop the index from the stack
        }
        stack.push(i); // Push the current index onto the stack
    }

    return result;
}

// --- End Monotonic Stack Implementation ---

// --- Usage Example ---

int main() {
    std::vector<int> nums = {4, 2, 3, 5};
    std::vector<int> result = nextGreaterElement(nums);

    for (int num : result) {
        std::cout << num << " ";
    }

    return 0;
}

// --- End Usage Example ---

