// --- Time Complexity: O(n * m) ---
// --- Space Complexity: O(min(n, m)) ---

#include <vector>
#include <string>
using namespace std;

// Function to compute the edit distance between two strings
int editDistance(const string& s1, const string& s2) {
    int n = s1.size(), m = s2.size();
    if (n > m) return editDistance(s2, s1); // Ensure n is always <= m to save space

    vector<int> dp(n + 1); // DP array to store distances

    // Initialize the base case
    for (int i = 0; i <= n; ++i) dp[i] = i;

    // Compute the edit distance
    for (int j = 1; j <= m; ++j) {
        int prev = dp[0]; // Store the value of dp[j-1][i-1]
        dp[0] = j; // Update dp[0] to j
        for (int i = 1; i <= n; ++i) {
            int temp = dp[i]; // Store the current value of dp[i]
            if (s1[i - 1] == s2[j - 1]) {
                dp[i] = prev; // Characters match, no operation needed
            } else {
                dp[i] = min({dp[i - 1], dp[i], prev}) + 1; // Min of insert, delete, replace + 1
            }
            prev = temp; // Update prev to the current value of dp[i]
        }
    }

    return dp[n]; // Return the edit distance
}

