// --- Pick's Theorem Implementation ---

// Time: O(1) — Space: O(1)

#include <vector>
#include <utility>

struct Point {
    long long x, y;
};

long long pickTheorem(const std::vector<Point>& polygon) {
    // Count interior and boundary points
    int I = 0, B = 0;
    for (size_t i = 0; i < polygon.size(); ++i) {
        size_t j = (i + 1) % polygon.size();
        I += __gcd(abs(polygon[i].x - polygon[j].x), abs(polygon[i].y - polygon[j].y));
        B += abs(polygon[i].x - polygon[j].x) + abs(polygon[i].y - polygon[j].y);
    }
    return I + B / 2 - 1;
}

