// --- cycle detection using DFS ---
bool has_cycle(const std::vector<std::vector<int>>& adj, int u, std::vector<bool>& visited, std::vector<int>& discovery_time, int parent) {
    visited[u] = true;
    discovery_time[u] = time++;

    for (int v : adj[u]) {
        if (!visited[v]) {
            if (has_cycle(adj, v, visited, discovery_time, u)) {
                return true;
            }
        } else if (v != parent) {
            return true;
        }
    }

    return false;
}

// --- main function to detect cycles in a graph ---
bool detect_cycle(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj = build_adjacency_list(edges, n);
    std::vector<bool> visited(n, false);
    std::vector<int> discovery_time(n, -1);

    int time = 0;
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            if (has_cycle(adj, i, visited, discovery_time, -1)) {
                return true;
            }
        }
    }

    return false;
}

