// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
    }
    return adj;
}

// --- Kahn's algorithm for topological sort ---
std::vector<int> kahn_toposort(const std::vector<std::vector<int>>& adj, int n) {
    std::vector<int> in_degree(n, 0);
    for (const auto& neighbors : adj) {
        for (int v : neighbors) {
            ++in_degree[v];
        }
    }

    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }

    std::vector<int> result;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        result.push_back(u);
        for (int v : adj[u]) {
            if (--in_degree[v] == 0) {
                q.push(v);
            }
        }
    }

    return result;
}

// --- DFS-based topological sort ---
void dfs_toposort(int u, const std::vector<std::vector<int>>& adj, std::stack<int>& st, std::vector<bool>& visited) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs_toposort(v, adj, st, visited);
        }
    }
    st.push(u);
}

std::vector<int> dfs_toposort(const std::vector<std::vector<int>>& adj, int n) {
    std::stack<int> st;
    std::vector<bool> visited(n, false);
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            dfs_toposort(i, adj, st, visited);
        }
    }

    std::vector<int> result;
    while (!st.empty()) {
        result.push_back(st.top());
        st.pop();
    }

    return result;
}

