// --- GCD and LCM Calculation ---

// Function to calculate the greatest common divisor (GCD) using Euclidean algorithm
long long gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b; // Calculate remainder
        a = temp; // Swap values
    }
    return a; // GCD is the last non-zero remainder
}

// Function to calculate the least common multiple (LCM) using GCD
long long lcm(long long a, long long b) {
    return (a / gcd(a, b)) * b; // LCM = (a * b) / GCD
}

// --- Extended Euclidean Algorithm ---

// Function to calculate the GCD and coefficients using Extended Euclidean algorithm
void extendedEuclidean(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1; // Coefficient of a
        y = 0; // Coefficient of b
        return;
    }
    long long x1, y1;
    extendedEuclidean(b, a % b, x1, y1); // Recursive call

    x = y1; // Update coefficient of a
    y = x1 - (a / b) * y1; // Update coefficient of b
}

// --- Usage Example ---

// Read input, calculate GCD and LCM, print output
int main() {
    long long a, b;
    std::cin >> a >> b;
    std::cout << "GCD: " << gcd(a, b) << std::endl;
    std::cout << "LCM: " << lcm(a, b) << std::endl;
    return 0;
}

