// --- Modular Arithmetic Functions ---

// Function to compute (a * b) % mod efficiently to avoid overflow
long long mod_mul(long long a, long long b, long long mod) {
    long long result = 0;
    a %= mod; // Ensure a is within the range [0, mod-1]
    while (b > 0) {
        if (b % 2 == 1) {
            result = (result + a) % mod; // Add a to result if b is odd
        }
        a = (a * 2) % mod; // Double a and take modulo
        b /= 2; // Halve b
    }
    return result;
}

// Function to compute the modular inverse of a under modulo mod using Fermat's Little Theorem
long long mod_inverse(long long a, long long mod) {
    return mod_pow(a, mod - 2, mod); // (a^(mod-2)) % mod is the modular inverse of a
}

// Function to compute (base^exp) % mod efficiently using binary exponentiation
long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod; // Ensure base is within the range [0, mod-1]
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = mod_mul(result, base, mod); // Multiply result by base and take modulo
        }
        base = mod_mul(base, base, mod); // Square base and take modulo
        exp /= 2; // Halve exp
    }
    return result;
}

// --- Complexity Note ---
// Time: O(log n) for each modular exponentiation and inverse computation
// Space: O(1)

