// --- Rabin-Karp Algorithm ---

// Time Complexity: O(n * m) in the worst case, but typically O(n + m)
// Space Complexity: O(1) excluding the input strings

#include <iostream>
#include <string>
#include <vector>

using namespace std;

const int MOD = 1e9 + 7;
const int BASE = 256;

// Function to calculate (base^power) % mod using iterative method
double powerMod(int base, int power) {
    double result = 1;
    while (power > 0) {
        if (power % 2 == 1)
            result = (result * base) % MOD;
        base = (base * base) % MOD;
        power /= 2;
    }
    return result;
}

// Function to find all occurrences of pattern in text using Rabin-Karp algorithm
vector<int> rabinKarp(const string& text, const string& pattern) {
    vector<int> result;
    int n = text.length();
    int m = pattern.length();
    if (m > n) return result;

    // Precompute base^m % mod
    double baseM = powerMod(BASE, m);

    // Compute hash of pattern and first window of text
    long long patternHash = 0, textHash = 0;
    for (int i = 0; i < m; ++i) {
        patternHash = (patternHash * BASE + pattern[i]) % MOD;
        textHash = (textHash * BASE + text[i]) % MOD;
    }

    // Slide the window over the text
    for (int i = 0; i <= n - m; ++i) {
        if (patternHash == textHash) {
            bool match = true;
            for (int j = 0; j < m; ++j) {
                if (text[i + j] != pattern[j]) {
                    match = false;
                    break;
                }
            }
            if (match)
                result.push_back(i);
        }
        // Compute hash for the next window
        if (i < n - m) {
            textHash = (textHash * BASE - text[i] * baseM + text[i + m]) % MOD;
            if (textHash < 0)
                textHash += MOD;
        }
    }

    return result;
}

// Example usage
int main() {
    string text = "ABABDABACDABABCABAB";
    string pattern = "ABABCABAB";
    vector<int> positions = rabinKarp(text, pattern);
    for (int pos : positions)
        cout << pos << " ";
    return 0;
}

