// --- String Hashing Implementation ---

// Time: O(n) — Space: O(n)

#include <vector>
#include <string>
#include <algorithm>

using namespace std;

// Function to compute the hash of a string using polynomial rolling hash
long long hashString(const string& s, int base, int modulus) {
    long long hash = 0;
    long long power = 1;

    // Iterate over each character in the string
    for (char c : s) {
        // Update the hash value using the polynomial formula
        hash = (hash + (c - 'A' + 1) * power) % modulus;
        // Update the power of the base
        power = (power * base) % modulus;
    }

    return hash;
}

// --- Usage Example ---

// Read input, compute hash, and print result
int main() {
    string s = "ABC";
    int base = 10;
    int modulus = 1000;

    long long hash = hashString(s, base, modulus);
    cout << "Hash of '" << s << "' is: " << hash << endl;

    return 0;
}

