// Segment Tree Implementation in C++17
// Time: O(n log n) for construction, O(log n) per query
// Space: O(n)

#include <vector>
#include <algorithm>

using namespace std;

template<typename T, typename F = plus<T>>
class SegmentTree {
private:
    vector<T> tree;
    F combine;
    T identity;

    // Helper function to build the segment tree
    void build(const vector<T>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2 * node, start, mid);
            build(arr, 2 * node + 1, mid + 1, end);
            tree[node] = combine(tree[2 * node], tree[2 * node + 1]);
        }
    }

    // Helper function to query the segment tree
    T query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return identity; // Out of range
        if (l <= start && end <= r) return tree[node]; // Inside range
        int mid = (start + end) / 2;
        T left = query(2 * node, start, mid, l, r);
        T right = query(2 * node + 1, mid + 1, end, l, r);
        return combine(left, right);
    }

public:
    // Constructor to initialize the segment tree
    SegmentTree(const vector<T>& arr, F f = plus<T>(), T id = T())
        : combine(f), identity(id) {
        int n = arr.size();
        tree.resize(4 * n);
        build(arr, 1, 0, n - 1);
    }

    // Function to query the segment tree for a range [l, r]
    T query(int l, int r) {
        return query(1, 0, tree.size() / 4 - 1, l, r);
    }
};

// --- usage example ---
// vector<int> arr = {3, 1, 4, 1, 5};
