// --- Segment Tree with Lazy Propagation ---

#include <vector>
#include <algorithm>

using namespace std;

// --- Segment Tree Node ---
struct Node {
    int value; // Value of the segment
    int lazy;  // Lazy propagation tag
};

// --- Segment Tree Class ---
class SegmentTree {
private:
    vector<Node> tree; // Segment tree array
    int n;              // Size of the input array

public:
    // Constructor to initialize the segment tree
    SegmentTree(const vector<int>& arr) : n(arr.size()), tree(4 * n) {
        build(arr, 0, n - 1, 1);
    }

    // Build the segment tree
    void build(const vector<int>& arr, int tl, int tr, int pos) {
        if (tl == tr) {
            tree[pos].value = arr[tl];
            tree[pos].lazy = 0;
        } else {
            int tm = (tl + tr) / 2;
            build(arr, tl, tm, pos * 2);
            build(arr, tm + 1, tr, pos * 2 + 1);
            tree[pos].value = tree[pos * 2].value + tree[pos * 2 + 1].value;
            tree[pos].lazy = 0;
        }
    }

    // Update a range with a value
    void updateRange(int l, int r, int val, int tl, int tr, int pos) {
        if (l > r) return; // Invalid range
        if (tl == l && tr == r) {
            tree[pos].value += (tr - tl + 1) * val;
            tree[pos].lazy += val;
        } else {
            push(pos);
            int tm = (tl + tr) / 2;
            updateRange(l, min(r, tm), val, tl, tm, pos * 2);
            updateRange(max(l, tm + 1), r, val, tm + 1, tr, pos * 2 + 1);
            tree[pos].value = tree[pos * 2].value + tree[pos * 2 + 1].value;
        }
    }

    // Query the sum of a range
    int query(int l, int r, int tl, int tr, int pos) {
        if (l > r) return 0; // Invalid range
        if (tl == l && tr == r) return tree[pos].value;
        push(pos);
        int tm = (tl + tr) / 2;
        return query(l, min(r, tm), tl, tm, pos * 2) + query(max(l, tm + 1), r, tm + 1, tr, pos * 2 + 1);
    }

private:
    // Push lazy updates to children
    void push(int pos) {
        if (tree[pos].lazy != 0) {
            tree[pos * 2].value += (tree[pos * 2].lazy * (tree[pos * 2].lazy + 1)) / 2;
            tree[pos * 2].lazy += tree[pos].lazy;
            tree[pos * 2 + 1].value += (tree[pos * 2 + 1].lazy * (tree[pos * 2 + 1].lazy + 1)) / 2;
            tree[pos * 2 + 1].lazy += tree[pos].lazy;
            tree[pos].lazy = 0;
        }
    }
};

// --- Complexity Note ---
// Time: O(n log n) for build, O(log n) for update and query
// Space: O(n)

