// --- Monotonic Deque Implementation ---

#include <vector>
#include <deque>

// Time: O(n) — Space: O(k)
class MonotonicDeque {
public:
    MonotonicDeque(bool increasing) : increasing(increasing) {}

    void push_back(int value) {
        // Remove elements from the back that are not in the desired order
        while (!dq.empty() && (increasing ? dq.back() < value : dq.back() > value)) {
            dq.pop_back();
        }
        dq.push_back(value);
    }

    void push_front(int value) {
        // Remove elements from the front that are not in the desired order
        while (!dq.empty() && (increasing ? dq.front() < value : dq.front() > value)) {
            dq.pop_front();
        }
        dq.push_front(value);
    }

    void pop_back() {
        if (!dq.empty()) {
            dq.pop_back();
        }
    }

    void pop_front() {
        if (!dq.empty()) {
            dq.pop_front();
        }
    }

    int front() const {
        return dq.front();
    }

    bool empty() const {
        return dq.empty();
    }

private:
    std::deque<int> dq;
    bool increasing;
};

