// --- dp array ---
std::vector<std::vector<long long>> dp(1 << n, std::vector<long long>(n, LLONG_MAX));
for (int u = 0; u < n; ++u) {
    dp[1 << u][u] = 0;
}

// --- bitmask dp transitions ---
for (int mask = 0; mask < (1 << n); ++mask) {
    for (int u = 0; u < n; ++u) {
        if ((mask & (1 << u)) == 0) continue;
        for (auto [v, w] : adj[u]) {
            if ((mask & (1 << v)) != 0) continue;
            dp[mask | (1 << v)][v] = std::min(dp[mask | (1 << v)][v], dp[mask][u] + w);
        }
    }
}

// --- result ---
long long result = LLONG_MAX;
for (int u = 0; u < n; ++u) {
    result = std::min(result, dp[(1 << n) - 1][u]);
}
std::cout << result << std::endl;

