// --- Bounded Knapsack ---

// Time: O(nW) — Space: O(W)

#include <vector>
#include <deque>
using namespace std;

// Function to solve the bounded knapsack problem
int boundedKnapsack(int W, vector<int>& weights, vector<int>& values, vector<int>& counts) {
    vector<int> dp(W + 1, 0);
    deque<int> dq;

    for (int i = 0; i < weights.size(); ++i) {
        int w = weights[i], v = values[i], c = counts[i];
        for (int j = W; j >= w; --j) {
            if (j - w >= 0 && dp[j - w] + v > dp[j]) {
                dp[j] = dp[j - w] + v;
                dq.push_back(j);
            } else {
                break;
            }
        }
        while (!dq.empty() && dq.front() < j - w) {
            dq.pop_front();
        }
    }

    return dp[W];
}

// --- Unbounded Knapsack ---

// Time: O(nW) — Space: O(W)

int unboundedKnapsack(int W, vector<int>& weights, vector<int>& values) {
    vector<int> dp(W + 1, 0);
    deque<int> dq;

    for (int i = 0; i < weights.size(); ++i) {
        int w = weights[i], v = values[i];
        for (int j = w; j <= W; ++j) {
            if (dp[j - w] + v > dp[j]) {
                dp[j] = dp[j - w] + v;
                dq.push_back(j);
            } else {
                break;
            }
        }
        while (!dq.empty() && dq.front() < j - w) {
            dq.pop_front();
        }
    }

    return dp[W];
}

