// --- base case ---
dp[0][0] = 1;

// --- fill dp table ---
for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= m; ++j) {
        if (i > 0) dp[i][j] += dp[i - 1][j]; // from top
        if (j > 0) dp[i][j] += dp[i][j - 1]; // from left
    }
}

